package authz

import (
	"time"

	"github.com/luwa07832/rbac-admin-api/internal/store"
)

// Service runs the time-aware authorization model over one store.
type Service struct {
	store *store.Store
}

// NewService wraps a store.
func NewService(st *store.Store) *Service { return &Service{store: st} }

// timings carries the canonical UTC texts of one write event.
type timings struct {
	occurredAt    string
	effectiveFrom string
}

// bindingRow is a flattened subject/role interval version.
type bindingRow struct {
	seq           int64
	roleID        string
	event         string
	occurredAt    string
	effectiveFrom string
	effectiveTo   string
	id            int64
}

// rolePermRow is a flattened role/permission interval version.
type rolePermRow struct {
	seq           int64
	roleID        string
	permissionID  string
	event         string
	occurredAt    string
	effectiveFrom string
	effectiveTo   string
	id            int64
}

// scopeRow is a flattened scoped authorization interval version. Exactly one
// of roleID and permissionID is set.
type scopeRow struct {
	seq           int64
	roleID        string
	permissionID  string
	scope         scopeRef
	event         string
	occurredAt    string
	effectiveFrom string
	effectiveTo   string
	id            int64
}

// snapshot is the complete read model needed for one decision or history
// query. Interval semantics are evaluated in Go in one place.
type snapshot struct {
	bindings []bindingRow
	rolePerm []rolePermRow
	scopes   []scopeRow

	// roleModel holds the current inheritance graph and the static operation
	// coverage of permissions; neither carries history intervals.
	roleModel
}

// roleModel is the history-free read model shared by every query: the
// current role inheritance graph in stored order and the operations
// statically covered by each permission.
type roleModel struct {
	roleParents    map[string][]string
	permOperations map[string]map[string]bool
}

func (s *Service) loadSnapshot(subject string) (*snapshot, error) {
	snap := &snapshot{roleModel: roleModel{
		roleParents:    map[string][]string{},
		permOperations: map[string]map[string]bool{},
	}}

	bindings, scopes, err := s.loadSubjectRows(subject)
	if err != nil {
		return nil, err
	}
	snap.bindings = bindings
	snap.scopes = scopes

	rolePermRows, err := s.loadRolePermissionRows()
	if err != nil {
		return nil, err
	}
	snap.rolePerm = rolePermRows

	model, err := s.loadRoleModel()
	if err != nil {
		return nil, err
	}
	snap.roleModel = model
	return snap, nil
}

// loadSubjectRows reads one subject's binding and scoped authorization
// interval versions. Scope rows that no longer parse are dropped, matching
// the read model everywhere else.
func (s *Service) loadSubjectRows(subject string) ([]bindingRow, []scopeRow, error) {
	bindingVersions, err := s.store.ListBindingVersions(subject)
	if err != nil {
		return nil, nil, err
	}
	bindings := make([]bindingRow, 0, len(bindingVersions))
	for _, version := range bindingVersions {
		bindings = append(bindings, bindingRow{
			seq:           version.Seq,
			roleID:        version.RoleID,
			event:         version.Event,
			occurredAt:    version.OccurredAt,
			effectiveFrom: version.EffectiveFrom,
			effectiveTo:   version.EffectiveTo,
			id:            version.ID,
		})
	}

	scopeVersions, err := s.store.ListScopeVersions(subject)
	if err != nil {
		return nil, nil, err
	}
	scopes := []scopeRow{}
	for _, version := range scopeVersions {
		parsedScope, ok := parseScope(version.ScopeText)
		if !ok {
			continue
		}
		scopes = append(scopes, scopeRow{
			seq:           version.Seq,
			roleID:        version.RoleID,
			permissionID:  version.PermissionID,
			scope:         parsedScope,
			event:         version.Event,
			occurredAt:    version.OccurredAt,
			effectiveFrom: version.EffectiveFrom,
			effectiveTo:   version.EffectiveTo,
			id:            version.ID,
		})
	}
	return bindings, scopes, nil
}

// loadRoleModel reads the current inheritance graph and static permission
// operation coverage. Both are present-time definitions without intervals.
func (s *Service) loadRoleModel() (roleModel, error) {
	model := roleModel{
		roleParents:    map[string][]string{},
		permOperations: map[string]map[string]bool{},
	}
	roleIDs, err := s.store.ListCatalog(store.CatalogRole)
	if err != nil {
		return roleModel{}, err
	}
	for _, roleID := range roleIDs {
		parents, err := s.store.RoleParents(roleID)
		if err != nil {
			return roleModel{}, err
		}
		model.roleParents[roleID] = parents
	}

	permissionIDs, err := s.store.ListCatalog(store.CatalogPermission)
	if err != nil {
		return roleModel{}, err
	}
	for _, permissionID := range permissionIDs {
		operations, err := s.store.PermissionOperations(permissionID)
		if err != nil {
			return roleModel{}, err
		}
		set := map[string]bool{}
		for _, operation := range operations {
			set[operation] = true
		}
		model.permOperations[permissionID] = set
	}
	return model, nil
}

// loadRolePermissionRows reads every role/permission grant interval version.
func (s *Service) loadRolePermissionRows() ([]rolePermRow, error) {
	rolePermVersions, err := s.store.ListRolePermissionVersions()
	if err != nil {
		return nil, err
	}
	rows := make([]rolePermRow, 0, len(rolePermVersions))
	for _, version := range rolePermVersions {
		rows = append(rows, rolePermRow{
			seq:           version.Seq,
			roleID:        version.RoleID,
			permissionID:  version.PermissionID,
			event:         version.Event,
			occurredAt:    version.OccurredAt,
			effectiveFrom: version.EffectiveFrom,
			effectiveTo:   version.EffectiveTo,
			id:            version.ID,
		})
	}
	return rows, nil
}

// resolveTimings resolves event and effective times. Both default to now;
// either may be supplied and effectiveFrom need not follow occurredAt.
func (s *Service) resolveTimings(occurredAtText, effectiveFromText string, effectiveField string) (timings, *Failure) {
	now := time.Now().UTC()
	result := timings{occurredAt: FormatTime(now), effectiveFrom: FormatTime(now)}
	if occurredAtText != "" {
		occurred, fail := ParseTime(occurredAtText)
		if fail != nil {
			fail.Field = "occurredAt"
			return timings{}, fail
		}
		result.occurredAt = FormatTime(occurred)
	}
	if effectiveFromText != "" {
		effective, fail := ParseTime(effectiveFromText)
		if fail != nil {
			fail.Field = effectiveField
			return timings{}, fail
		}
		result.effectiveFrom = FormatTime(effective)
	}
	return result, nil
}

// rowActive reports whether the half-open interval [from,to) contains t; an
// empty to marks an open interval.
func rowActive(from, to, at string) bool {
	if from > at {
		return false
	}
	return to == "" || to > at
}
package authz

import (
	"bytes"
	"encoding/json"
	"fmt"
	"sort"
	"time"
)

// MaxBatchQueries is the inclusive upper bound on one batch authorize call.
const MaxBatchQueries = 100

// BatchInput is the payload for POST /authorize/batch. EffectiveAtText is the
// raw optional RFC3339 timestamp shared by every query; Queries carries each
// query as a generic JSON value so the service can validate item shape itself.
type BatchInput struct {
	EffectiveAtText *string
	Queries         []json.RawMessage
}

// BatchResultItem is the public echo of one query plus the decision for it.
type BatchResultItem struct {
	Subject   string    `json:"subject"`
	Resource  string    `json:"resource"`
	Operation string    `json:"operation"`
	Decision  *Decision `json:"decision"`
}

// BatchDecide validates the whole batch against one shared moment and then
// evaluates every query in input order. Structure validation has already
// rejected a missing, empty, non-array or oversized queries array at the
// entry; here the effectiveAt is parsed before the first per-query check,
// and queries are validated by index: shape, then identifier grammar, then
// catalog existence in subject/resource/operation order. Duplicate triples
// stay separate and no partial result is ever returned.
func (s *Service) BatchDecide(in BatchInput) ([]BatchResultItem, *Failure) {
	at := time.Now().UTC()
	if in.EffectiveAtText != nil {
		parsed, fail := ParseTime(*in.EffectiveAtText)
		if fail != nil {
			return nil, fail
		}
		at = parsed
	}

	validated := make([]DecisionInput, len(in.Queries))
	for index, raw := range in.Queries {
		input, fail := validateBatchQuery(raw, index)
		if fail != nil {
			return nil, fail
		}
		if fail := s.checkTriple(input.Subject, input.Resource, input.Operation); fail != nil {
			fail.Field = fmt.Sprintf("queries[%d].%s", index, fail.Field)
			return nil, fail
		}
		validated[index] = input
	}

	// Each subject's snapshot is loaded once; identical triples are evaluated
	// repeatedly so duplicates keep producing their own decision.
	snapshots := map[string]*snapshot{}
	results := make([]BatchResultItem, len(validated))
	for index, input := range validated {
		snap, ok := snapshots[input.Subject]
		if !ok {
			loaded, err := s.loadSnapshot(input.Subject)
			if err != nil {
				return nil, failure(TypeInvalidRequest, "", "could not evaluate authorization")
			}
			snap = loaded
			snapshots[input.Subject] = snap
		}
		results[index] = BatchResultItem{
			Subject:   input.Subject,
			Resource:  input.Resource,
			Operation: input.Operation,
			Decision:  evaluate(snap, input.Resource, input.Operation, at),
		}
	}
	return results, nil
}

// validateBatchQuery checks one element of the queries array. It must be a
// JSON object containing exactly the subject, resource and operation string
// fields; grammar is checked before catalog existence, each in the published
// subject/resource/operation order.
func validateBatchQuery(raw json.RawMessage, index int) (DecisionInput, *Failure) {
	field := func(name string) string {
		return fmt.Sprintf("queries[%d].%s", index, name)
	}
	baseField := fmt.Sprintf("queries[%d]", index)

	trimmed := bytes.TrimSpace(raw)
	if len(trimmed) == 0 || trimmed[0] != '{' {
		return DecisionInput{}, invalidRequest(baseField, "queries entry must be a JSON object")
	}
	var fields map[string]json.RawMessage
	if err := json.Unmarshal(trimmed, &fields); err != nil {
		return DecisionInput{}, invalidRequest(baseField, "queries entry must be a JSON object")
	}

	names := make([]string, 0, len(fields))
	for name := range fields {
		if name != "subject" && name != "resource" && name != "operation" {
			names = append(names, name)
		}
	}
	if len(names) > 0 {
		sort.Strings(names)
		return DecisionInput{}, invalidRequest(field(names[0]), "field is not allowed on a batch query")
	}

	var input DecisionInput
	pairs := []struct {
		name string
		dest *string
	}{
		{"subject", &input.Subject},
		{"resource", &input.Resource},
		{"operation", &input.Operation},
	}
	for _, pair := range pairs {
		rawValue, present := fields[pair.name]
		if !present {
			return DecisionInput{}, invalidRequest(field(pair.name), "field "+pair.name+" is required")
		}
		var text string
		if err := json.Unmarshal(rawValue, &text); err != nil {
			return DecisionInput{}, invalidRequest(field(pair.name), "field "+pair.name+" must be a string")
		}
		*pair.dest = text
	}

	for _, pair := range pairs {
		if !validIdentifier(*pair.dest) {
			return DecisionInput{}, invalidRequest(field(pair.name), "field "+pair.name+" is not a parseable identifier")
		}
	}
	return input, nil
}

