	envelope := batchRaw(h, `{"effectiveAt":"2026-02-01T00:00:00Z","queries":[
		{"subject":"user-1","resource":"tenant-a/doc-1","operation":"read"}]}`)
	if fmt.Sprint(envelope.Decisions[0].Decision) != fmt.Sprint(single) {
