	batchExpectError(t, h, `{"queries":"read"}`, http.StatusBadRequest, "INVALID_REQUEST", "queries")
	batchExpectError(t, h, `{"queries":[]}`, http.StatusBadRequest, "INVALID_REQUEST", "queries")
