	wantPaths := []any{
		wantPath("ROLE", "viewer", "viewer", "doc-read", "tenant-a/*"),
	}
	if !reflect.DeepEqual(item["paths"], wantPaths) {
		raw, _ := json.Marshal(item["paths"])
		t.Fatalf("paths = %s, want one deduplicated path", raw)
	}
}

func TestAuthorizeBatchExplainNormalizesAndDefaultsEffectiveAt(t *testing.T) {
	h := newHarness(t)
	seedBatchBaseline(h)

	view := batchExplainRaw(t, h, `{
		"effectiveAt":"2026-02-01T08:00:00+08:00",
		"queries":[
			{"subject":"user-1","resource":"tenant-a/doc-1","operation":"read"}
		]}`)
	if view["effectiveAt"] != "2026-02-01T00:00:00Z" {
		t.Fatalf("effectiveAt = %v", view["effectiveAt"])
	}
	if explanationAt(t, view, 0)["decision"].(map[string]any)["granted"] != true {
		t.Fatalf("decision = %v", explanationAt(t, view, 0)["decision"])
	}

	// Omitted or null effectiveAt means now: the long-open baseline is active.
	current := batchExplainRaw(t, h, `{"queries":[
		{"subject":"user-1","resource":"tenant-a/doc-1","operation":"read"}]}`)
	before := time.Now().UTC()
	effectiveText, ok := current["effectiveAt"].(string)
	if !ok || effectiveText == "" {
		t.Fatalf("effectiveAt = %v", current["effectiveAt"])
	}
	parsed, err := time.Parse(time.RFC3339, effectiveText)
	if err != nil {
		t.Fatalf("parse effectiveAt %q: %v", effectiveText, err)
	}
	if parsed.Before(before.Add(-time.Minute)) || parsed.After(time.Now().UTC().Add(time.Minute)) {
		t.Fatalf("effectiveAt %v is not the current time", parsed)
	}
	if explanationAt(t, current, 0)["decision"].(map[string]any)["granted"] != true {
		t.Fatalf("current decision = %v", explanationAt(t, current, 0)["decision"])
	}

	nullTime := batchExplainRaw(t, h, `{"effectiveAt":null,"queries":[
		{"subject":"user-1","resource":"tenant-a/doc-1","operation":"read"}]}`)
	if explanationAt(t, nullTime, 0)["decision"].(map[string]any)["granted"] != true {
		t.Fatalf("null-time decision = %v", explanationAt(t, nullTime, 0)["decision"])
	}
}

func TestAuthorizeBatchExplainReadOnlyAndIdempotent(t *testing.T) {
	h := newHarness(t)
	seedBaseline(h)
	grantAt(h, "/subjects/user-1/bindings/viewer", nil)
	grantAt(h, "/roles/viewer/permissions/doc-read", nil)
	grantAt(h, "/subjects/user-1/scopes", map[string]any{"role": "viewer", "scope": "tenant-a/*"})

	historyTarget := "/history?subject=user-1&resource=" + enc("tenant-a/doc-1") + "&operation=read"
	eventsBefore := history(h, historyTarget)["events"]
	body := `{"effectiveAt":"2026-02-01T00:00:00Z","queries":[
		{"subject":"user-1","resource":"tenant-a/doc-1","operation":"read"},
		{"subject":"user-1","resource":"tenant-b/doc-2","operation":"read"}]}`
	first := batchExplainRaw(t, h, body)
	second := batchExplainRaw(t, h, body)

	if eventsAfter := history(h, historyTarget)["events"]; !reflect.DeepEqual(eventsBefore, eventsAfter) {
		t.Fatalf("history changed: %v -> %v", eventsBefore, eventsAfter)
	}
	if !reflect.DeepEqual(second["explanations"], first["explanations"]) ||
		second["effectiveAt"] != first["effectiveAt"] {
		t.Fatalf("repeat batch explain differs: %v vs %v", second, first)
	}

	// The read does not change later authorization outcomes.
	recorder := h.request(http.MethodPost, "/authorize", map[string]any{
		"subject": "user-1", "resource": "tenant-a/doc-1", "operation": "read",
		"effectiveAt": "2026-02-01T00:00:00Z",
	})
	h.mustStatus(recorder, http.StatusOK)
	single := mustJSON(t, recorder)["decision"].(map[string]any)
	item := explanationAt(t, first, 0)
	if fmt.Sprint(item["decision"]) != fmt.Sprint(single) {
		t.Fatalf("decision after batch explain %v != authorize %v", item["decision"], single)
	}
}

