func TestAuthorizeBatchExplainNormalizesSharedTime(t *testing.T) {
	h := newHarness(t)
	seedBatchBaseline(h)

	envelope := batchExplainRaw(h, `{
		"effectiveAt":"2026-02-01T08:00:00+08:00",
		"queries":[
